![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

If the state file is corrupted or contains non-dictionary JSON data, `data.get` or dictionary assignment will raise an error. Also, allow `applied` and `warnings` to accept `"-"` to avoid overwriting the last run's statistics when updating only the notification timestamp.

```shell
    python3 - "$STATE_FILE" "$platform" "$last_success_at" "$last_mode" "$applied" "$warnings" "$notified_at" <<'PY'
import json, os, sys
path, platform, success, mode, applied, warnings, notified = sys.argv[1:8]
try:
    with open(path, "r", encoding="utf-8") as handle:
        data = json.load(handle)
except Exception:
    data = {}
if not isinstance(data, dict):
    data = {}
entry = data.get(platform, {})
if not isinstance(entry, dict):
    entry = {}
if success != "-":
    entry["last_success_at"] = int(success)
if mode != "-":
    entry["last_mode"] = mode
if applied != "-":
    entry["last_applied_count"] = int(applied)
if warnings != "-":
    entry["last_warning_count"] = int(warnings)
entry["last_version"] = "1.0.0"
if notified != "-":
    entry["last_notified_at"] = int(notified)
data[platform] = entry
tmp = path + ".tmp"
os.makedirs(os.path.dirname(path), exist_ok=True)
with open(tmp, "w", encoding="utf-8") as handle:
    json.dump(data, handle, sort_keys=True, indent=2)
    handle.write("\n")
os.replace(tmp, path)
PY
```

